<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,ref,watch} from 'vue'
import {MapPin,ChevronRight,ArrowRight} from 'lucide-vue-next'
import AmapCityMap from './AmapCityMap.vue'
import {mapPoints,locationUsable,type MapLocation} from '../amap'
import {journey,loadJourney,nameOf,scenicIdFor,updateCity,confirmCity,addChoice,choice,focusedDraftDay,focusDay,tripDays,canUseFocusedDay} from '../journey'
import type {CityProposal} from '../cityApi'
const props=defineProps<{placeId?:string;view?:string}>(),selected=ref(props.placeId||''),showAll=ref(true),search=ref(''),locationValue=ref<MapLocation|null>(null),message=ref(''),saving=ref(false),proposal=ref<Extract<CityProposal,{status:'needs_confirmation'}>>()
const points=computed(()=>mapPoints(journey.catalog,journey.trip,journey.route,journey.focusedDayId))
const places=computed(()=>points.value.filter(p=>(showAll.value||p.state!=='已有地点')&&p.name.includes(search.value.trim())))
const currentId=computed(()=>selected.value||points.value.find(p=>p.state==='下一站')?.id||places.value[0]?.id)
const current=computed(()=>points.value.find(p=>p.id===currentId.value))
const scenic=computed(()=>current.value?scenicIdFor(current.value.name):undefined)
const record=computed(()=>journey.catalog.find(p=>p.record.kind==='place'&&p.record.fact_id===currentId.value))
const missing=computed(()=>focusedDraftDay.value?.stops.filter(s=>!points.value.some(p=>p.id===s.place_id))||[])
const revision=computed(()=>[journey.trip?.id,journey.trip?.version,journey.trip?.route_version,journey.focusedDayId,journey.route?.stale].join(':'))
const savedLocation=ref<MapLocation|null>(null)
function useSaved(){const anchor=journey.trip?.anchor,p=anchor&&points.value.find(p=>p.id===anchor.place_id);if(!anchor||!p||p.coordinateSystem!=='GCJ02'){message.value='保存位置无可用 GCJ-02 坐标，请重新手动选择';return}const loc:MapLocation={position:p.position,coordinate_system:'GCJ02',source:'manual_known_place',method:'saved_user_anchor',obtained_at:anchor.confirmed_at,accuracy_m:null,place_id:p.id};if(!locationUsable(loc)){message.value='保存位置已过期，请重新确认';return}savedLocation.value=loc}
async function savePosition(){if(!current.value||!journey.trip||saving.value||!canUseFocusedDay.value)return;saving.value=true;message.value='';try{const result=await updateCity({operation:'set_anchor',day_id:tripDays.value.length>1?focusedDraftDay.value?.day_id:undefined,anchor:{place_id:current.value.id,confirmed_at:new Date().toISOString()}});if(result.proposal?.status==='needs_confirmation')proposal.value=result.proposal;else message.value='已保存手动已知地点，小汴梁会读取同一旅行位置'}catch(e){message.value=(e as Error).message}finally{saving.value=false}}
async function confirmPosition(){if(!proposal.value)return;saving.value=true;try{await confirmCity(proposal.value);proposal.value=undefined;message.value='旅行位置已确认，小汴梁与行程共用此状态'}catch(e){message.value=(e as Error).message}finally{saving.value=false}}
watch(()=>props.placeId,v=>selected.value=v||'');watch(()=>journey.trip?.id,()=>{proposal.value=undefined;savedLocation.value=null;message.value=''});watch(revision,()=>proposal.value=undefined)
function refresh(){void loadJourney(true)}
onMounted(()=>{refresh();window.addEventListener('focus',refresh)})
onBeforeUnmount(()=>window.removeEventListener('focus',refresh))
</script>
<template><div class="city-map-workspace"><div class="city-map-task"><span class="tiny-caption">{{journey.trip?'本次旅行 · 路线版本 '+journey.trip.route_version:'自由探索'}}</span><h2>{{current?current.name:'开封城市地图'}}</h2><p v-if="!journey.trip?.route_version">尚无已确认路线；地图地点不代表正式安排。</p><p v-else-if="!journey.route||journey.route.stale">正式路线待加载或已失效，请先核对行程。</p><p v-else>地图与正式行程共用版本、完成进度及锁定目标。</p><p v-if="view&&view!=='city'">景区视角仅展示有依据的点位；园内道路尚待核验。</p></div><nav v-if="tripDays.length>1" class="trip-day-selector" aria-label="地图日期"><button v-for="d in tripDays" :key="d.day_id" :aria-pressed="d.day_id===focusedDraftDay?.day_id" @click="focusDay(d.day_id);selected=''">{{d.business_date}} · {{d.business_date===new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai'}).format(new Date())?'今天':'查看'}}</button></nav><p v-if="!canUseFocusedDay">此日仅供查看，不作为今天的下一站。</p><AmapCityMap :points="places" :selected="currentId" :view="view" :revision="revision" :data-route-revision="revision" :owner="journey.trip?.id" :saved-location="savedLocation" @select="selected=$event" @location="locationValue=$event"/><div class="city-map-controls"><label class="map-search">搜索已知地点<input v-model="search" placeholder="地点名称" aria-label="搜索已知地点"/></label><button class="button secondary" @click="showAll=!showAll">{{showAll?'只看正式行程':'全部已有地点'}}</button><button v-if="journey.trip?.anchor" class="button secondary" @click="useSaved">使用已保存位置</button><button class="button secondary" @click="loadJourney(true)">刷新行程资料</button></div><p v-if="journey.error" class="error-state" role="alert">{{journey.error}}</p><p v-if="message" class="trip-warning" role="status">{{message}}</p><p v-if="missing.length" class="map-empty-note">以下安排缺少有效坐标，未绘制：{{missing.map(s=>nameOf(s.place_id)).join('、')}}。</p><div class="map-place-picks"><button v-for="p in places" :key="p.id" :class="{active:currentId===p.id}" @click="selected=p.id"><MapPin :size="15"/><span>{{p.name}}<small>{{p.state}}{{p.locked?' · 锁定目标':''}} · {{p.entrance?'核验入口':p.type==='restaurant'?'商家':p.type==='stage'?'舞台':'地点 POI'}}</small></span><ChevronRight :size="16"/></button></div><p v-if="!places.length" class="map-empty-note">暂无匹配且坐标来源有效的地点；不会补造地图点位。</p><section v-if="current" class="map-current-card"><div><span class="tiny-caption">{{current.state}}{{current.locked?' · 锁定目标':''}}</span><h2>{{current.name}}</h2><p>{{record?.record.address||'详细地址待核实'}}</p><p>{{current.entrance?'已核验入口关系，开放情况仍需核对当日公告':'地点位置，不能当作已核验入口或园内通行依据'}}</p></div><div><RouterLink :to="'/place/'+current.id" class="button secondary">查看详情</RouterLink><RouterLink v-if="scenic" :to="'/guide?scenic='+scenic" class="button secondary">进入园内游览</RouterLink><button class="button secondary" @click="addChoice(choice('place',current.id,current.name))">加入素材篮</button><button v-if="journey.trip" class="button primary" :disabled="saving||!canUseFocusedDay" @click="savePosition">确认我在此已知地点，并设为旅行当前位置</button></div><p v-if="locationValue&&locationValue.source!=='manual_known_place'">定位点为临时位置；此操作保存的是你明确选择的已知地点，不保存原始定位坐标。</p></section><section v-if="proposal" class="amap-anchor-confirm"><p>位置调整需要确认：{{proposal.impacts.join('；')}}</p><button class="button primary" :disabled="saving" @click="confirmPosition">确认更新旅行位置</button><button class="button secondary" @click="proposal=undefined">暂不更新</button></section><RouterLink v-if="journey.trip" class="map-trip-return" :to="'/city-trip/'+journey.trip.id">继续我的行程 <ArrowRight :size="15"/></RouterLink></div></template>
<style scoped>.map-search{display:flex;flex:1 1 100%;align-items:center;gap:10px;font-size:13px}.map-search input{min-width:0;max-width:100%;flex:1;padding:10px;border:1px solid #d8d0bb;border-radius:8px;background:#fffdf8}.city-map-controls{flex-wrap:wrap}.map-current-card>div:last-child{display:flex;flex-wrap:wrap;gap:8px}.amap-anchor-confirm{padding:14px;background:#f8f3e5;border-radius:12px}.city-map-workspace{min-width:0}.map-place-picks small{white-space:normal}</style>
